<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Damage report #<?= (int)$report['report_id'] ?> | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/rentals/detail?agreement_id=<?= (int)$report['agreement_id'] ?>">Agreement #<?= (int)$report['agreement_id'] ?></a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Damage report #<?= (int)$report['report_id'] ?></p><h1><?= $e(strtoupper($report['phase'])) ?> inspection</h1><p>Recorded <?= $e($report['created_at']) ?> by <?= $e($report['recorded_by_email']) ?></p></div></section><section class="panel"><h2><?= (int)$report['has_damage']===1?'Damage recorded':'No damage found' ?></h2><?php if((int)$report['has_damage']===1):?><p>Location: <?= $e($report['location']) ?> · Type: <?= $e($report['damage_type']) ?> · Severity: <?= $e($report['severity']) ?></p><p>Repair cost suggestion: ₱<?= $e($report['repair_cost_suggestion']??'Not entered') ?></p><?php endif;?><?php if($report['notes']):?><p><?= $e($report['notes']) ?></p><?php endif;?><h3>Evidence</h3><?php if(!$report['photos']):?><p>No photographs were attached.</p><?php else:foreach($report['photos'] as $photo):?><p><a href="/rentals/damage/photo?photo_id=<?= (int)$photo['photo_id'] ?>" target="_blank" rel="noopener"><?= $e($photo['original_filename']) ?></a> · <?= number_format(((int)$photo['size_bytes'])/1024,1) ?> KB</p><?php endforeach;endif;?></section><section class="panel"><h2>Liability decision history</h2><?php if(!$report['decisions']):?><p>No liability decision recorded.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>When / by</th><th>Finding</th><th>Amount</th><th>Reason</th><th>Supersedes</th></tr></thead><tbody><?php foreach($report['decisions'] as $decision):?><tr><td><?= $e($decision['created_at'].' / '.$decision['actor_email']) ?></td><td><?= (int)$decision['customer_liable']===1?'Customer liable':'Customer not liable' ?></td><td>₱<?= $e($decision['liable_amount']) ?></td><td><?= $e($decision['reason']) ?></td><td><?= $decision['supersedes_decision_id']===null?'Initial decision':'#'.(int)$decision['supersedes_decision_id'] ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="panel"><h2>Damage charge review</h2><?php if(!$report['postings']):?><p>No damage charge has been posted.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>When / by</th><th>Approved amount</th><th>Adjustment reason</th><th>Charge</th></tr></thead><tbody><?php foreach($report['postings'] as $posting):?><tr><td><?= $e($posting['created_at'].' / '.$posting['actor_email']) ?></td><td>₱<?= $e($posting['approved_amount']) ?></td><td><?= $e($posting['adjustment_reason']??'No adjustment') ?></td><td><?= $e($posting['charge_description']) ?> · ₱<?= $e($posting['charge_amount']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></body></html>
